mapper.update:
UPDATE t_user_permission
SET effect = #{userPermission.effect},
    data_scope_code = #{userPermission.dataScopeCode},
    effective_from = #{userPermission.effectiveFrom},
    effective_to = #{userPermission.effectiveTo},
    active_marker = 1,
    reason = #{userPermission.reason},
    granted_by = #{userPermission.grantedBy},
    version = version + 1,
    update_time = #{userPermission.updateTime}
WHERE user_id = #{userPermission.userId}
  AND permission_id = #{userPermission.permissionId}
  AND version = #{expectedVersion}

mapper.select:
SELECT 
FROM t_user_permission
WHERE user_id = #{userId}
  AND permission_id = #{permissionId}
  AND active_marker=1
  AND effective_from <= #{effectiveAt}
  AND (effective_to IS NULL OR effective_to > #{effectiveAt})
